-- A biblioteca de exercícios e alongamentos: 450 exercícios e 60 alongamentos, com
-- o músculo principal, os secundários e o equipamento. Ainda sem imagens de demonstração
-- (images = 0); os passos de execução estão em /exercise-library/steps.<língua>.json.
-- Os exercícios antigos mantêm o id, para os treinos já registados; os tipos de treino (SPORT) nunca se alteram.
ON CONFLICT ("id") DO UPDATE SET
    "category" = EXCLUDED."category",
    "unit" = EXCLUDED."unit",
    "group" = EXCLUDED."group",
    "muscles" = EXCLUDED."muscles",
    "equipment" = EXCLUDED."equipment",
    "weighted" = EXCLUDED."weighted",
    "images" = EXCLUDED."images",
    "holdSec" = EXCLUDED."holdSec",
    "position" = EXCLUDED."position"
WHERE "ExerciseType"."category" <> 'SPORT';
